                        className={css({
                          marginLeft: "0.5rem",
                          display: "inline-flex",
                          alignItems: "center",
                          fontSize: "0.75rem",
                          color: "var(--primary)",
                          textDecoration: "underline",
                          textUnderlineOffset: "2px",
                        })}
                      >
                        Need a key?
                      </a>
                    </div>
                  </div>
                </div>
              )}
            </div>
            {llmFailure && canRetry && onRetry && (
              <FailedResponseRecovery
                recovery={llmFailure.recovery}
                onRetry={onRetry}
              />
            )}
            {llmFailure && retryAttempts && retryAttempts > 1 && (
              <p
                className={css({
                  marginTop: "0.5rem",
                  fontSize: "0.75rem",
                  color: "var(--muted-foreground)",
