		{rows ? <div className={css({ display: "grid", gap: "0.75rem" })}>{node.items?.map((item, rowIndex) => <div key={`${node.id}-${rowIndex}`} className={css({ display: "grid", gap: "0.375rem", border: "1px solid var(--border)", borderRadius: "0.5rem", padding: "0.625rem" })}>
			<strong>{item}</strong>
			<select disabled={disabled} className={input} aria-label={`${node.choiceLabel ?? "Choice"} for ${item}`} value={rowSelections[rowIndex]} onChange={(event) => setRowSelections((current) => current.map((value, index) => index === rowIndex ? event.currentTarget.value : value))}><option value="">Select…</option>{node.choices?.map((choice) => <option key={choice.id} value={choice.id} disabled={node.kind === "matching" && node.uniqueMatches !== false && rowSelections.some((selected, index) => index !== rowIndex && selected === choice.id)}>{choice.label}</option>)}</select>
			{node.requireReasons ? <input disabled={disabled} className={input} aria-label={`${node.reasonLabel ?? "Reason"} for ${item}`} value={rowReasons[rowIndex]} onChange={(event) => setRowReasons((current) => current.map((value, index) => index === rowIndex ? event.currentTarget.value : value))} placeholder={node.reasonLabel ?? "Reason"} /> : null}
		</div>)}</div>
			: blanks ? <div className={css({ display: "grid", gap: "0.375rem" })}>{blankAnswers.map((value, index) => <input disabled={disabled} key={`${node.id}-blank-${index}`} className={input} aria-label={`Blank ${index + 1}`} value={value} onChange={(event) => setBlankAnswers((current) => current.map((entry, entryIndex) => entryIndex === index ? event.currentTarget.value : entry))} placeholder={node.blanks?.[index]?.placeholder ?? `Blank ${index + 1}`} />)}</div>
				: node.choices ? <div className={css({ display: "grid", gap: "0.375rem" })}>{node.choices.map((choice) => <label key={choice.id} className={css({ display: "flex", alignItems: "center", gap: "0.5rem" })}><input disabled={disabled} type={multiple ? "checkbox" : "radio"} name={node.id} checked={selected.includes(choice.id)} onChange={() => setSelected((current) => multiple ? current.includes(choice.id) ? current.filter((id) => id !== choice.id) : [...current, choice.id] : [choice.id])} />{choice.label}</label>)}</div>
					: node.kind === "slider" ? <div className={css({ display: "grid", gap: "0.375rem" })}><input disabled={disabled} type="range" min={node.min ?? 0} max={node.max ?? 100} step={node.step ?? 1} value={answer || node.min || 0} onChange={(event) => setAnswer(event.currentTarget.value)} /><output>{answer || node.min || 0}</output></div>
						: <textarea disabled={disabled} className={input} value={answer} onChange={(event) => setAnswer(event.currentTarget.value)} placeholder="Type your answer" />}
		{node.hint ? <small>{node.hint}</small> : null}
		<button className={button} type="button" disabled={disabled || !ready} onClick={submit}>Submit answer</button>
	</fieldset>;
}

function Checklist({ title, nodeId, items, actionType, disabled, onAction }: { title: string; nodeId: string; items: Array<{ id: string; title: string; done: boolean }>; actionType: "complete-goal-step" | "complete-plan-item"; disabled: boolean; onAction?: (event: SharedUiActionEvent) => void }) {
	const [done, setDone] = useState(() => new Set(items.filter((item) => item.done).map((item) => item.id)));
	return <div className={section}><h4 className={css({ fontWeight: 700 })}>{title}</h4>{items.map((item) => <label key={item.id} className={css({ display: "flex", gap: "0.5rem" })}><input disabled={disabled} type="checkbox" checked={done.has(item.id)} onChange={() => { const next = new Set(done); next.has(item.id) ? next.delete(item.id) : next.add(item.id); setDone(next); onAction?.(actionType === "complete-goal-step" ? { type: actionType, humanFriendlyMessage: `${next.has(item.id) ? "Completed" : "Reopened"}: ${item.title}`, params: { nodeId, stepId: item.id } } : { type: actionType, humanFriendlyMessage: `${next.has(item.id) ? "Completed" : "Reopened"}: ${item.title}`, params: { nodeId, itemId: item.id, completed: next.has(item.id) } }); }} />{item.title}</label>)}</div>;
}

function Plan({ nodeId, title, overview, items, disabled, onAction }: { nodeId: string; title: string; overview?: string; items: UiStudyPlanItem[]; disabled: boolean; onAction?: (event: SharedUiActionEvent) => void }) {
	return <div className={section}><h4 className={css({ fontWeight: 700 })}>{title}</h4>{overview ? <MarkdownBlock content={overview} /> : null}<PlanItems nodeId={nodeId} items={items} disabled={disabled} onAction={onAction} /></div>;
}

function PlanItems({ nodeId, items, disabled, onAction }: { nodeId: string; items: UiStudyPlanItem[]; disabled: boolean; onAction?: (event: SharedUiActionEvent) => void }) {
	return <ul className={css({ display: "grid", gap: "0.5rem", paddingLeft: "1rem" })}>{items.map((item) => <li key={item.id}><Checklist title={item.title} nodeId={nodeId} items={[{ id: item.id, title: item.detail ?? item.title, done: item.status === "done" }]} actionType="complete-plan-item" disabled={disabled} onAction={onAction} />{item.children ? <PlanItems nodeId={nodeId} items={item.children} disabled={disabled} onAction={onAction} /> : null}</li>)}</ul>;
}

function Notes({ node, disabled, onAction }: { node: Extract<UiDocumentNode, { type: "notes" }>; disabled: boolean; onAction?: (event: SharedUiActionEvent) => void }) {
	const [value, setValue] = useState(node.value);
	return <div className={section}><label htmlFor={node.id} className={css({ fontWeight: 700 })}>{node.title}</label><textarea disabled={disabled} id={node.id} className={input} value={value} placeholder={node.placeholder} onChange={(event) => setValue(event.currentTarget.value)} /><button disabled={disabled} className={button} type="button" onClick={() => onAction?.({ type: "update-notes", humanFriendlyMessage: `Updated ${node.title}`, params: { nodeId: node.id, value } })}>Save notes</button></div>;
}

function Deck({ node, disabled, onAction }: { node: Extract<UiDocumentNode, { type: "deck" }>; disabled: boolean; onAction?: (event: SharedUiActionEvent) => void }) {
	const [index, setIndex] = useState(0);
	const [revealed, setRevealed] = useState(false);
	const card = node.cards[index];
	if (!card) return <div className={section}>This deck has no cards.</div>;
	return <div className={section}><h4 className={css({ fontWeight: 700 })}>{node.title}</h4><button disabled={disabled} className={button} type="button" onClick={() => setRevealed((value) => !value)}>{revealed ? card.back : card.front}</button>{revealed ? <div className={css({ display: "flex", flexWrap: "wrap", gap: "0.375rem" })}>{["Again", "Hard", "Good", "Easy"].map((label, rating) => <button disabled={disabled} key={label} className={button} type="button" onClick={() => { onAction?.({ type: "rate-card", humanFriendlyMessage: `${label}: ${card.front}`, params: { nodeId: node.id, cardId: card.id, rating } }); setRevealed(false); setIndex((index + 1) % node.cards.length); }}>{label}</button>)}</div> : null}</div>;
}

function Resource({ title, content, uri, markdown = false }: { title: string; content?: string; uri?: string; markdown?: boolean }) {
	return <div className={section}><h4 className={css({ fontWeight: 700 })}>{title}</h4>{content ? markdown ? <MarkdownBlock content={content} /> : <pre className={css({ overflowX: "auto", whiteSpace: "pre-wrap" })}>{content}</pre> : null}{uri ? <a className={button} href={uri} target="_blank" rel="noreferrer">Open resource</a> : null}</div>;
}

function Media({ node }: { node: Extract<UiDocumentNode, { type: "media" }> }) {
	if (node.kind === "audio") return <div className={section}><strong>{node.resource.title}</strong><audio controls src={node.resource.uri} /></div>;
	if (node.kind === "video") return <div className={section}><strong>{node.resource.title}</strong><video controls src={node.resource.uri} className={css({ maxWidth: "100%" })} /></div>;
	return <Resource title={node.resource.title} uri={node.resource.uri} content="Animation opens only from its validated resource URL." />;
}
import {
	UI_CONTRACT_VERSION,
	WEB_OPENUI_COMPONENTS,
	type UiDeckCard,
	type UiDocument,
	type UiDocumentNode,
	type UiOption,
	type UiQuestion,
	type UiQuestionLevel,
	type UiQuestionType,
	type UiStudyPlanItem,
	type UiStudyPlanLink,
	validateUiDocument,
} from "@keating/learner-contracts";
import { createParser, type ElementNode } from "@openuidev/react-lang";
import { keatingOpenUILibrary } from "./library";

export interface CompileSharedOpenUIOptions {
	documentId: string;
	revision?: number;
	createdAt?: string;
	updatedAt?: string;
}

export const SHARED_OPENUI_COMPONENT_MAPPERS = [
	"LearningSurface", "Explanation", "Callout", "Question", "Quiz", "Flashcards",
	"StudyPlan", "ConceptMap", "LearningImage", "LearningAnimation", "SharedNotes",
] as const satisfies typeof WEB_OPENUI_COMPONENTS;

const parser = createParser(keatingOpenUILibrary.toJSONSchema());

function record(value: unknown): Record<string, unknown> {
	return value && typeof value === "object" && !Array.isArray(value) ? value as Record<string, unknown> : {};
}

function text(value: unknown, fallback = ""): string {
	return typeof value === "string" ? value : fallback;
}

function optionalText(value: unknown): string | undefined {
	return typeof value === "string" ? value : undefined;
}

function textArray(value: unknown): string[] | undefined {
	if (!Array.isArray(value) || !value.every((entry) => typeof entry === "string")) return undefined;
	return value;
}

function numberValue(value: unknown): number | undefined {
	return typeof value === "number" && Number.isFinite(value) ? value : undefined;
}

function booleanValue(value: unknown): boolean | undefined {
	return typeof value === "boolean" ? value : undefined;
}

function contractId(value: string, fallback: string): string {
	const normalized = value
		.normalize("NFKD")
		.replace(/[^a-zA-Z0-9._:-]+/g, "-")
		.replace(/^-+|-+$/g, "")
		.slice(0, 128);
	return normalized || fallback;
}

function childId(parent: string, kind: string, index?: number): string {
	return contractId(`${parent}-${kind}${index === undefined ? "" : `-${index + 1}`}`, `${kind}-${(index ?? 0) + 1}`);
}

function elementId(element: ElementNode, fallback: string): string {
	return contractId(element.statementId ?? fallback, fallback);
}

function choices(parent: string, value: unknown): UiOption[] | undefined {
	const entries = textArray(value);
	return entries?.map((label, index) => ({ id: childId(parent, "choice", index), label }));
}

function blanks(value: unknown): UiQuestion["blanks"] {
	if (!Array.isArray(value)) return undefined;
	return value.map((entry) => {
		const item = record(entry);
		return { ...(optionalText(item.placeholder) !== undefined ? { placeholder: text(item.placeholder) } : {}), ...(optionalText(item.hint) !== undefined ? { hint: text(item.hint) } : {}) };
	});
}

function question(parent: string, value: unknown, index: number, quiz = false): UiQuestion {
	const item = record(value);
	const fallbackId = childId(parent, "question", index);
	const id = quiz ? contractId(`${parent}-${text(item.id, `question-${index + 1}`)}`, fallbackId) : fallbackId;
	const rawKind = text(item.type, quiz ? "short_answer" : "choice") as UiQuestionType;
	const optionSource = quiz ? item.options : item.choices;
	const mappedChoices = choices(id, optionSource) ?? (rawKind === "true_false" ? [{ id: childId(id, "true"), label: "True" }, { id: childId(id, "false"), label: "False" }] : undefined);
	const result: UiQuestion = {
		id,
		prompt: text(item.question, "Question"),
		kind: rawKind,
		...(optionalText(item.header) !== undefined ? { header: text(item.header) } : {}),
		...(mappedChoices ? { choices: mappedChoices } : {}),
		...(textArray(item.items) ? { items: textArray(item.items) } : {}),
		...(blanks(item.blanks) ? { blanks: blanks(item.blanks) } : {}),
		...(optionalText(item.hint) !== undefined ? { hint: text(item.hint) } : {}),
		...(booleanValue(item.allowText) !== undefined ? { allowText: booleanValue(item.allowText) } : {}),
		...(booleanValue(item.multiSelect) !== undefined || rawKind === "multi_select" ? { multiSelect: booleanValue(item.multiSelect) ?? true } : {}),
		...(booleanValue(item.requireReasons) !== undefined ? { requireReasons: booleanValue(item.requireReasons) } : {}),
		...(optionalText(item.itemLabel) !== undefined ? { itemLabel: text(item.itemLabel) } : {}),
		...(optionalText(item.choiceLabel) !== undefined ? { choiceLabel: text(item.choiceLabel) } : {}),
		...(optionalText(item.reasonLabel) !== undefined ? { reasonLabel: text(item.reasonLabel) } : {}),
		...(booleanValue(item.uniqueMatches) !== undefined ? { uniqueMatches: booleanValue(item.uniqueMatches) } : {}),
		...(textArray(item.correctMatches) ? { correctMatches: textArray(item.correctMatches) } : {}),
		...(optionalText(item.level) !== undefined ? { level: text(item.level) as UiQuestionLevel } : {}),
		...(optionalText(item.correctAnswer) !== undefined ? { correctAnswer: text(item.correctAnswer) } : {}),
		...(textArray(item.correctAnswers) ? { correctAnswers: textArray(item.correctAnswers) } : {}),
		...(optionalText(item.explanation) !== undefined ? { explanation: text(item.explanation) } : {}),
		...(optionalText(item.rubric) !== undefined ? { rubric: text(item.rubric) } : {}),
		...(numberValue(item.timeLimit) !== undefined ? { timeLimit: numberValue(item.timeLimit) } : {}),
		...(numberValue(item.min) !== undefined ? { min: numberValue(item.min) } : {}),
		...(numberValue(item.max) !== undefined ? { max: numberValue(item.max) } : {}),
		...(numberValue(item.step) !== undefined ? { step: numberValue(item.step) } : {}),
	};
	return result;
}

function planItem(value: unknown, index: number, parent = "plan"): UiStudyPlanItem {
	const item = record(value);
	const id = contractId(text(item.id, childId(parent, "item", index)), childId(parent, "item", index));
	const children = Array.isArray(item.children) ? item.children.map((child, childIndex) => planItem(child, childIndex, id)) : undefined;
	return {
		id,
		title: text(item.title, "Study item"),
		...(optionalText(item.detail) !== undefined ? { detail: text(item.detail) } : {}),
		...(textArray(item.dependsOn) ? { dependsOn: textArray(item.dependsOn)?.map((dependency) => contractId(dependency, "dependency")) } : {}),
		...(numberValue(item.estimatedMinutes) !== undefined ? { estimatedMinutes: numberValue(item.estimatedMinutes) } : {}),
		...(textArray(item.outcomes) ? { outcomes: textArray(item.outcomes) } : {}),
		status: "not_started",
		...(children?.length ? { children } : {}),
	};
}

function planLink(value: unknown, index: number): UiStudyPlanLink {
	const link = record(value);
	const relation = optionalText(link.relation);
	return {
		planId: contractId(text(link.planId, `related-plan-${index + 1}`), `related-plan-${index + 1}`),
		title: text(link.title, "Related plan"),
		...(relation === "prerequisite" || relation === "follow-up" || relation === "related" ? { relation } : {}),
		...(optionalText(link.detail) !== undefined ? { detail: text(link.detail) } : {}),
	};
}

function mapElement(element: ElementNode, index: number): UiDocumentNode[] {
	const id = elementId(element, `openui-node-${index + 1}`);
	const props = element.props;
	switch (element.typeName) {
		case "Explanation": {
			const title = optionalText(props.title);
			return [{ type: "markdown", id, markdown: `${title ? `### ${title}\n\n` : ""}${text(props.markdown)}` }];
		}
		case "Callout": return [{ type: "callout", id, markdown: text(props.markdown), tone: text(props.tone, "info") as "info" | "hint" | "check" | "warning", ...(optionalText(props.title) ? { title: text(props.title) } : {}) }];
		case "Question": return Array.isArray(props.questions) ? props.questions.map((entry, questionIndex) => ({ type: "question", ...question(id, entry, questionIndex) })) : [];
		case "Quiz": return [{ type: "quiz", id: contractId(text(props.id, id), id), title: text(props.topic, "Quiz"), questions: Array.isArray(props.questions) ? props.questions.map((entry, questionIndex) => question(id, entry, questionIndex, true)) : [] }];
		case "Flashcards": return [{
			type: "deck", id: contractId(text(props.id, id), id), title: text(props.title, "Flashcards"), topic: text(props.topic, "Study"),
			cards: Array.isArray(props.cards) ? props.cards.map((entry, cardIndex): UiDeckCard => {
				const card = record(entry);
				return { id: contractId(text(card.id, childId(id, "card", cardIndex)), childId(id, "card", cardIndex)), front: text(card.front, "Front"), back: text(card.back, "Back"), ...(textArray(card.tags) ? { tags: textArray(card.tags) } : {}) };
			}) : [],
		}];
		case "StudyPlan": return [{
			type: "study-plan", id: contractId(text(props.id, id), id), title: text(props.title, "Study plan"),
			...(optionalText(props.overview) ? { overview: text(props.overview) } : {}),
			items: Array.isArray(props.items) ? props.items.map((entry, itemIndex) => planItem(entry, itemIndex, id)) : [],
			...(Array.isArray(props.relatedPlans) ? { relatedPlans: props.relatedPlans.map(planLink) } : {}),
		}];
		case "ConceptMap": return [{ type: "concept-map", id, source: text(props.code), ...(optionalText(props.title) ? { title: text(props.title) } : {}) }];
		case "LearningImage": return [{ type: "image", id, alt: text(props.alt, "Learning image"), resource: { id: childId(id, "resource"), title: text(props.title, "Learning image"), format: "uri", uri: text(props.src) } }];
		case "LearningAnimation": return [{ type: "handoff", id, target: "web", reason: text(props.summary, `Open the ${text(props.topic, "learning")} animation in Keating web`), context: "The source interaction contains executable HTML, so the portable learner contract records an explicit trusted-surface handoff instead of embedding or executing it." }];
		case "SharedNotes": return [{ type: "notes", id: contractId(text(props.id, id), id), title: text(props.title, "Learner notes"), value: text(props.initialValue), ...(optionalText(props.placeholder) ? { placeholder: text(props.placeholder) } : {}) }];
		default: throw new Error(`OpenUI component ${element.typeName} has no shared semantic mapping.`);
	}
}

/** Compile the browser OpenUI language into the versioned cross-surface contract. */
export function compileOpenUISourceToSharedDocument(source: string, options: CompileSharedOpenUIOptions): UiDocument {
	const result = parser.parse(source);
	if (!result.root || result.root.typeName !== "LearningSurface") throw new Error("OpenUI source has no LearningSurface root.");
	if (result.meta.incomplete || result.root.partial) throw new Error("OpenUI source is incomplete.");
	if (result.meta.errors.length || result.meta.unresolved.length) throw new Error("OpenUI source contains invalid or unresolved components.");
	const content = result.root.props.content;
	if (!Array.isArray(content) || !content.every((entry) => record(entry).type === "element")) throw new Error("OpenUI LearningSurface content is invalid.");
	const at = options.updatedAt ?? options.createdAt ?? new Date().toISOString();
	const document: UiDocument = {
		schemaVersion: UI_CONTRACT_VERSION,
		id: contractId(options.documentId, "openui-document"),
		revision: options.revision ?? 0,
		lifecycle: "ready",
		supportedSurfaces: ["web", "desktop", "mobile", "terminal"],
		...(optionalText(result.root.props.title) ? { title: text(result.root.props.title) } : {}),
		...(optionalText(result.root.props.description) ? { description: text(result.root.props.description) } : {}),
		nodes: content.flatMap((entry, index) => mapElement(entry as ElementNode, index)),
		createdAt: options.createdAt ?? at,
		updatedAt: at,
	};
	if (!validateUiDocument(document)) throw new Error("Compiled OpenUI document does not satisfy the shared learner contract.");
	return document;
}

